import sys

def maximize_rectangle(rows, cols, board):
    best_area = 0
    odd_rows, even_rows = 0, 0
    even_cols, odd_cols = 0, 0

    # Marking rows and columns
    for row in board:
        if all(cell == '#' for cell in row):
            odd_rows += 1
        else:
            odd_rows += row.count('#')
            even_rows += row.count('#')

    for col in zip(*board):
        if all(cell == '#' for cell in col):
            odd_cols += 1
        else:
            odd_cols += col.count('#')
            even_cols += col.count('#')

    # Calculating maximum area
    current_area = 0
    for i in range(min(cols, rows)):
        col_total = cols - i
        row_total = len(board) - i
        half_total = i // 2

        current_area = half_total * col_total *
                        max(0, half_total + odd_rows - even_cols - even_rows)

    return current_area

def read_input():
