from functools import lru_cache

@lru_cache(maxsize=None)
def win_probability(bears, places, days):
    if bears == 0:
        return 1
    if days == 0:
        return 0
    result = win_probability(bears, places - 1, days - 1)
    if bears >= places * (days - 1):
        return win_probability(bears, places, days - 1)
    return result

def xor(limit):
    b = bin(limit)[2:]
    return int(b[0] + '0' * (len(b) - 1), 2) ^ int(b[1] + '0' * (len(b) - 2), 2)

MOD = 10**9 + 7

def calculate_xor(limit):
    return xor(limit) % MOD

