from functools import lru_cache

class BearGame:
    def __init__(self, n, p, q):
        self.n = n
        self.p = p
        self.q = q

    def solve(self):
        self.known = {}
        for q in range(1, self.q + 1):
            if q in self.known:
                continue
            self.known[q] = self.determine_max_paintworthy(q)

    def determine_max_paintworthy(self, nights):
        if nights < 2:
            return 1

        def dfs(hours, barrels):
            if (hours, barrels) in self.known:
                return self.known[(hours, barrels)]

            if barrels == 0:
                return 1

            max_wine = 0
            for i in range(1, barrels + 1):
                if i % 2 == 0:
                    berries = self.determine_max_paintworthy(nights - hours)
                    if berries:
                        max_wine = max(max_wine, i * berries)

            self.known[(hours, barrels)] = max_wine
            return max_wine

        wines = dfs(nights, self.n)
        return wines * (2 ** nights - 1)

if __name__ == "__main__":
    n, p, q = map(int, input().split())
    solution = BearGame(n, p, q)
    solution.solve()
    print(solution.known[q])
