import sys
from typing import List

def min_cost_for_each_student(n, q, k, tickets, student_ranges):
    """
    Determine the minimum money each student needs to spend to attend gym for dates described.
    """
    tickets_used = [0] * (n + 1)
    min_cost = []

    for r in range(n):
        for l in range(r + 1, max(r + k, n + 1)):
            for day in range(l, r + 1):
                tickets_used[day] += tickets[day - l + 1]
                min_cost.append(sum(v for v in tickets_used[r + 1] if v > 0))

    return min_cost[::-1]

class Reader:
    def __init__(self):
        self.stdin = sys.stdin
        self.reader = sys.stdin.buffer if sys.platform == 'win32' else sys.stdin

    def getint(self, expected_type='int'):
        if expected_type == 'int':
            return int(next(self.reader))
        return next(self.reader)

    def getints(self, n):
        if expected_type == 'int':
            return tuple(map(int, next(self.reader).split(' ')))
        return next(map(int, next(self.reader).split(' ')))

