class WeightedTree:
    def __init__(self, n):
        self.graph = [{} for _ in range(n)]
        self.weights = []

    def add_edge(self, u, v, w):
        self.graph[u][v] = w
        self.graph[v][u] = w
        self.weights.append(w)

    def shortest_path(self, start, end):
        dist = [0] * len(self.weights)
        dist[start] = 0

        for _ in range(len(self.weights) - 1):
            for i in range(len(self.weights)):
                if dist[i] == 0:
                    dist[i] = self.weights[i]

        for i in range(n - 2, -1, -1):
            for j in range(len(self.weights)):
                if j in self.graph[i] and dist[j] > dist[i] + self.weights[j]:
                    dist[j] = dist[i] + self.weights[j]

        return dist[end] ^ 7

    def query(self, type_id, a, b, l, r, v):
        if type_id == 1:
            ans = [v - 1]
            if a % 2 == 1:
                ans.append(self.shortest_path(a, l) ^ v - 1)
                ans.append(self.shortest_path(b, l) ^ v - 1)
                if a + 2 <= r:
                    ans.append(self.shortest_path(a, a + 1) ^ v - 1)
                    ans.append(self.shortest_path(b, b + 1) ^ v - 1)
                if b + 1 <= r and a + 1 <= l:
                    ans.append(self.shortest_path(a, b) ^ v - 1)
                    ans.append(self.shortest_path(a + 1, b + 1) ^ v - 1)
            if a % 2 == 0:
                ans.append(self.shortest_path(a, l) ^ v - 1)
                ans.append(self.shortest_path(b, b - 1) ^ v - 1)
                if b % 2 == 1 and a + 2 <= r:
                    ans.append(self.shortest_path(a, a + 2) ^ v - 1)
                    ans.append(self.shortest_path(b, a + 2) ^ v - 1)
                if a + 2 <= r and b + 1 <= l:
                    ans.append(self.shortest_path(b, b + 1) ^ v - 1)
                    ans.append(self.shortest_path(a, b + 1) ^ v - 1)
            return ans
        if type_id == 2:
            return v ^ self.shortest_path(a, a + 1)


def main():
    n, q = map(int, input().split())
    tree = WeightedTree(n)
    for _ in range(n - 1):
        u, v, w = map(int, input().split())
        tree.add_edge(u - 1, v - 1, w)

    for _ in range(q):
        type_id, a, b, l, r, v = map(int, input().split())
        tree.query(type_id, a, b, l, r, v)


if __name__ == "__main__":
    main()
