from collections import deque

def max_distance(K, N, D, obstacles):
    state = {0: 0}
    frontier = deque([0])
    used = set()

    while frontier:
        cur = frontier.popleft()
        for next_position in range(1 + (cur + K), K + 1):
            if next_position in obstacles:
                new_state = cur + next_position
                if new_state > max_distance_D and (next_position in obstacles) == next_position:
                    state[next_position] = cur + next_position
                    used.add(next_position)
            elif next_position not in state and (next_position in obstacles) == next_position:
                frontier.append(next_position)
                state[next_position] = cur + next_position
                used.add(next_position)
        used.add(cur)

    if len(used) == N:
        return K
    next_max = max_distance_D
    for next_position in range(1 + max(state), K + 1):
        if next_position not in state and (next_position in obstacles) == next_position:
            next_max = min(next_max, state[next_position] + D)

    return next_max

def max_distance_D(K, obstacles):
    max_distance = 0
    for obstacle in obstacles:
        obstacle_distance = K - obstacle
        continue_distance = 0
        while obstacle_distance > 0:
            obstacle_distance -= K
            if obstacle_distance <= 0:
                break
            continue_distance += 1
        max_distance = max(max_distance, continue_distance + obstacle)
    return max_distance
