                solutions.append([i] * n)
                continue

            if i <= n-x and i != b[i-1]:
                for val in range(n+1):
                    # Modify i to a valid value considering y constraint
                    new_i = i - (y - max(b))
                    if new_i > 0 and new_i <= n-x and b[new_i-1] != i:
                        solutions.append([val] + b[:i-1] + [new_i] + b[i:n])
                        break

