import sys

def invert_row_column(grid, i, j):
    # Invert the colors of a row
    for k in range(len(grid[i])):
        grid[i][k] = '#' if grid[i][k] == '.' else '.'
    # Invert the colors of a column
    for k in range(len(grid)):
        grid[k][j] = '#' if grid[k][j] == '.' else '.'  

def find_max_rectangle(grid, S):
    H, W = len(grid), len(grid[0])
    max_area = 0

    # Check for each pair of row and column inversion
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                max_area = max(max_area, calculate_max_rectangle_inverted(grid, i, j, S))
                # Swap the color of the row or column
                if i < W - 1:
                    invert_row_column(grid, i, j)
                if j < H - 1: 
                    invert_row_column(grid, i, j)

    return max_area

def calculate_max_rectangle_inverted(grid, i, j, S):
    H, W = len(grid), len(grid[0])
    max_area = 0

    start = 0
    end = (H - 1) - i + 1
    for current in range(start, end + 1):
        if S[i + current][j] == '.':
            max_area = max(max_area, current + 1)
        elif S[i + current][j] == '#':
            while S[i + current][j] == '#':
                max_area = max(max_area, current + 1)
                current += 1
            break

    start = 0
    end = (W - 1) - j + 1
    for current in range(start, end + 1):
        if S[i][j - current] == '.':
            max_area = max(max_area, current + 1)
        elif S[i][j - current] == '#':
            while S[i][j - current] == '#':
                max_area = max(max_area, current + 1)
                current += 1
            break

