from heapq import heappush, heappop
from math import inf

class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.edges = {}
        for i in range(1, vertices + 1):
            self.edges[i] = []

    def add_edge(self, u, v, weight):
        self.edges[u].append((v, weight))
        self.edges[v].append((u, weight))

def dijkstra(graph, start, k):
    vertices = list(graph.edges.keys())
    distances = [inf] * (vertices + 1)
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance = heappop(priority_queue)[1]
        if current_distance > distances[current_distance]:
            continue
        for neighbor, weight in graph.edges[current_distance]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))

    answer = []
    for distances1 in [distances, distances[::-1]]:
        for i in range(1, len(distances1)):
            distance = i
            found = False
            while distance <= k:
                if distances1[distance] == 0:
                    found = True
                    break
                k -= distances1[distance]
                distance += 1
            if found:
                answer.append(distance - 1)
                break

    answer = sorted(answer)
    return answer[-1] if len(answer) > 0 else answer[0]

n, k = map(int, input().split())
graph = Graph(n)
for _ in range(n - 1):
    start, end, weight = map(int, input().split())
    graph.add_edge(start, end, weight)

result = dijkstra(graph, 1, k)
