from math import factorial
from functools import lru_cache

def is_valid_state(state):
    for i in range(2):
        if state[(i*3):(i*3+3)] in ("GRR", "RGR", "RRG", "GRG", "RRB", "RBG", "RBB", "BGR", "BGG", "BBR"):
            return False
    return True

@lru_cache(maxsize=None)
def expect_time(state, level):
    if not is_valid_state(state):
        return 0
    if level >= 6:
        return float('inf')
    if len(set(state[:6])) == 1 and len(set(state[1:] + state[:-1])) == 1:
        return float('inf')
    current = ''.join(state[level*3::3])
    expected = []
    for i in range(2):
        for j in range(2):
            new_state = set(state[:6]).difference((i*3 + j, i*3 + j + 1))
            if level < 2 or i in range(3) or j in range(3):
                expected.append(4 * expect_time(tuple(sorted(new_state)), level - 1))
    if current == state[5]:
        expected.extend((3 + 4 * i) * 0.5 ** (level ** 2) for i in range(2, 6))
    for i, count in enumerate(expected):
        expected[i] = 1 / factorial(len(expected)) * sum(expected[:i] + [count] + expected[i:])
    return sum(expected) / factorial(len(expected))

if __name__ == "__main__":
    n = int(input())
    towers = [input() for _ in range(n)]
    print("%.7f" % (expect_time(tuple(sorted(towers[0])), n) > 63.3 or n > 1))
