import math

def calculate_expectation(levels):
    total_minutes = 0
    last_colored_level = len(levels) - 1
    for i in range(len(levels) - 1, 0, -1):
        color_sum = levels[i].count('R') + levels[i].count('G') + levels[i].count('B')
        if color_sum == 2:
            next_level = [levels[i-1][0], levels[i-1][2], ']']
        else:
            next_level = levels[i-1]
        if 'R' in next_level or 'G' in next_level or 'B' in next_level:
            min_mins = min(color_sum, 2)
            max_mins = max(color_sum, 2)
            if color_sum == 1:
                max_mins = min(max_mins, next_level.count('R') + next_level.count('G') + next_level.count('B'))
            next_level = unflatten_str(next_level, next_level.count('R'), next_level.count('G'), next_level.count('B'))
            total_minutes += 6 - i
    return total_minutes

def unflatten_str(level, prefix_count, mid_count, postfix_count):
    prefix = level[:prefix_count]
    mid_index = level[1:2]
    switcher = {
        'R': (level[2:4], level[4:6]),
        'G': (level[2:4], level[4:6]),
        'B': (level[2:4], level[4:6]),
    }
    if mid_index == 'R':
        return prefix + switcher['R'][0]
    if mid_index == 'G':
        return prefix + switcher['G'][0]
    if mid_index == '[':
        return prefix + switcher['B'][0]

    return prefix + mid_count * mid_index + postfix_count * 'R'[mid_index == '+']

def main():
    n = int(input())
    levels = [input().strip() for _ in range(n)]
    print(round(calculate_expectation(levels), 10))

if __name__ == "__main__":
