import math

def min_transfers(n, stocks):
    prices = [a * t + b / 100 for a, b in stocks]

    dp = [float('inf')] * (n * 2 + 1)
    dp[1] = 0

    for t in range(1, n + 2):
        for i in range(1, n * 2 + 1):
            if dp[i] == float('inf'):
                continue
            if prices[2 * i - 2] > prices[2 * i - 1]:
                dp[i + 2] = min(dp[i + 2], dp[i] + 1)
            else:
                dp[i + 1] = min(dp[i + 1], dp[i] + 1)

