from collections import defaultdict
from math import gcd

mod = 10**9 + 7

# build adjacency list
def build_adjacency_list(n, edges):
    adjacency_list = defaultdict(list)
    for u, v in edges:
        adjacency_list[u - 1].append(v - 1)
        adjacency_list[v - 1].append(u - 1)
    return adjacency_list

# preprocess height of each node
def preprocess_height(adjacency_list):
    height = [0] * n
    def dfs(node, depth):
        height[node] = depth
        for neighbor in adjacency_list[node]:
            dfs(neighbor, depth + 1)
    dfs(0, 1)
    return height

# calculate number of ways to paint tree such that distance to nearest black vertex <= k
def ways_to_paint_tree(n, k, height):
    ways = [1] * n
    for node in range(n):
        distance_heights = defaultdict(list)
        for k_subtree in (height - k, height + k):
            if k_subtree not in height:
                continue
            for node_subtree in range(len(k_subtree)):
                distance_heights[node_subtree].append(k_subtree[node_subtree])
        total_ways = 1
        for node_subtree, subtree_height in distance_heights.items():
            subtree_min_distance = bottom_right(smallest_maxima(subtree_height), n - k)
            subtree_hidden_total_ways = pow(
                total_ways, gcd(subtree_min_distance, n - subtree_min_distance - 1), mod
            )
            ways[node] *= (total_ways - subtree_hidden_total_ways + 1) % mod
            ways[node] %= mod
            total_ways *= remainder((sum(subtree_height) + k), mod)
            total_ways %= mod
    return ways[0]

def smallest_maxima(l):
    return max((a, b) for a, b in zip(l, list(range(len(l)))))

def bottom_right(l):
    return l[len(l) - len(l) % 2][len(l) // 2]

def remainder(l):
    return pow(l, power, mod)

def power(base, exp):
    if exp == 0:
        return 1
    if exp % 2 == 1:
        return base * power(base, exp - 1) % mod
    hi = power(base, exp // 2)
    return pow(hi, 2, mod)

if __name__ == "__main__":
