    input = sys.stdin.read
    data = list(map(int, input().split()))
    n = data[0]
    k = data[1]
    edges = [list(map(int, input().strip().split())) for i in range(n - 1)]
    adjacency_list = build_adjacency_list(n, edges)
    height = preprocess_height(adjacency_list)
    print(ways_to_paint_tree(n, k, height))
