def max_distance(N, K, D, obstacles):
    max_dist = 0
    for xi, Li in zip(obstacles[:-1], obstacles[1:]):
        xi += 1  # Skip the obstacle at X=Li
        dist = max((xi - k)[Li^1] + D for k in range(Li)) if Li == Li^1 else 0
        if dist:
            max_dist = max(max_dist, dist)
    return max(max_dist, K)
