        for neighbor in edge_list[start]:
            if not feasible[color_map[neighbor]] in power_table or not is_divisor(temporary, feasible[color_map[neighbor]]):
                feasible[color_map[start]] += 1
                dfs(edge_list, visited, neighbor, color_map, depth + 1, height, feasible, power_table)

def paint_trees(edge_count, max_distance, power_table, n):
    edge_list = [[] for _ in range(edge_count)]
    for u, v in edge_list:
        if u < v:
            edge_list[u].append(v)
        else:
            edge_list[v].append(u)
    for i in range(edge_count - 1):
        u = i + 1
        v = i + 2
        edge_list[u].append(v)
        edge_list[v].append(u)

    feasible = defaultdict(int)
    dfs(edge_list, {0, 1} - set(), 0, feasible, 1, max_distance + 1, feasible, power_table)

