import math

def solve(n, p, q):
    if p == 0:
        ans = 1
    else:
        ans = 1 << (p - 1)
    if p == 8:
        ans -= 2
    for i in range(q):
        if i == 0 or i == q // 2-1:
            if p == 1:
                continue
            elif p == 2 or p == 8:
                ans += 2
            else:
                ans += 1
        else:
            ans += (1 << (p-1)) * (p-2)  # The answer is the xor of the previous ans and the answer for the previous night increased by one
            if i == q // 2 - 1:
                ans ^= 2 ** (p - 1)  # Toggle the last night
    x = ans // 2
    g = int(3 ** (math.log2(x) + 1)) + 1
    ans = ((1 << (p - 1)) * (x - g) + ans) % ((1 << (p - 1)) * (x - g) + 2 + (1 << (p - 1)))
