        for bi in range(k):
            bracket_passes[i+1][i][bi] = tBi = bracket_passes[i][i][bi]
            for c_i in range(k):
                te = (c_i - bi) % k
                d = (t + te) % 2
                c_t = c_i * d
                tBd = (tBi - c_t) % k
