import sys

def min_exchanges_and_time(current_time, stock_prices, n):
    stock_counts = [0] * (2 ** n + 1)
    stock_prices.sort()
    for price in stock_prices:
        current_time = max(current_time, price // (-n))
        for i in range(1, 2 ** n + 1):
            if (i - sum(stock_counts[j] * price // (-j) for j in range(0, n + 1, 2)) > -price) and 
               (i - sum(stock_counts[j] * price // (-j) for j in range(1, n + 1, 2)) > -price):
                stock_counts[i] += 1
        if sum(stock_counts[i] * price // (-i) for i in range(1, n + 1, 2)) == 1:
            current_time = min(current_time, -price // (-n))
    if current_time != sys.maxsize:
        return current_time, sum(stock_counts[-n:-1])
    else:
        return -1

