MOD = 998244353

# Function to calculate F(B, K) with given array modification
def calculate_forward(B, K):
    total = 0
    for i in range(K):
        for j in range(i, K):
            total += B[i] * B[j]
            total %= MOD
    return total

# Function to calculate F(B, K) with given array query
def calculate_backward(B, K):
    total = 0
    for i in range(K):
        for j in range(K):
            total += B[i] * B[j] * B[i + j]
            total %= MOD
    return total

# Function to calculate F(B, K) with given query
def query_forward(q, i, d, K):
    return calculate_forward(B(q, A), K) * d

def query_backward(q, L, R, d, K):
    partial = calculate_backward(B(q+1, A), K)
    prefix = 0
    for i in range(L-1, R):
        prefix += B[i] * d
        prefix %= MOD
    if L-1 < 0:
        return d * (partial // (K-R)) + (prefix * (K-R-1))
    return d * (partial // (K-R)) + (prefix + ((K-R-1)*B[L-1] * partial // (K-R)))

