def query1(l, r, v, data):
    if l == r:
        return data[(v-1) | data[0]] ^ 1
    lowbit = l % 2
    ans = data[(v-1) | data[lowbit]] ^ 1
    if r - l < 2:
        return ans
    return ans & ((1 << r) - 1)

def query2(l, data):
