from collections import defaultdict

def count_paths(n, m, strings, b, q):
    mod = 10**9 + 7
    paths = defaultdict(list)

    for string in strings:
        permutations = []
        for char in b:
            if char in ''.join(sorted(list(string))):  # Ensure order of characters is correct
                cDict = defaultdict(int)
                # Convert characters to indices
                for char in b:
                    cDict[char] = 0
                for index, char in enumerate(string):
                    cDict[char] += index + 1
                permutations.append(cDict)
        paths[str(b)].extend(permutations)

    def get_count(b):
        pathDict = defaultdict(int)
        for i in range(m):
            for char in b:
                if i+1 in paths[str(b)][i]:
                    pathDict[(char, i)] += 1
        total_paths = 0
        for per in pathDict.values():
            total_paths += per
        return total_paths

    return [get_count(b) % mod for b in q]

