        self.vals.append(val)

    def dfs(self, i: int, j: int, d: int):
        q = 1 + (d - 1) * 4
        for _ in range(q):
            q += (d - 2) * 2
            if i > 0:
                q += 1
            if j > 0:
                q += 1
            idx = (i + j) % 4
            self.add_val((i, j, idx))
            i, j = self.dfs(i - d, j - d, d - 1)

    def nth_val(self, n: int):
        q = 1
        i = j = 0
        k = 0
        while q <= n:
            q += (d - 2) * 2
            if i > 0:
                q += 1
            if j > 0:
                q += 1
            idx = (i + j) % 4
            if q == n and k == 0:
                n -= q
                i, j, idx = self.vals[-1]
                todo = 3 - idx
                for _ in range(todo // 2):
                    i += 1
                    j += 1
                    idx = 3 - idx
                    q += 1
            if n > q:
                k += 1
                i, j, idx = self.vals.pop()
            else:
                n -= q
                i, j, idx = self.vals[-1]
        return i, j, idx

