def solve(n, s, q, q_strings):
    base = [calc_moves(s[i][0], 'a') for i in range(n)]
    ans = 0
    for i in range(q):
        c = q_strings[i]
        m1 = ord(c[0]) - ord('a')
        m2 = ord(c[1]) - ord('a')
        if m1 % 4 == m2 % 4:
