                f1, r1 = divmod((m2 - m1), 4)
                ans_add = (base[0] ** f1) * (calc_moves(c[0], 'a') ** f1) * (base[0] ** (m1 - f1)) * (base[0] ** r1) % 1000000007
            else:
                ans_add = (base[0] ** m1) * (calc_moves(c[0], 'a') ** m1) % 1000000007
            for j in range(n):
                if (m1 // 4 + j == m2 // 4) and (m1 % 4 != 0):
