                elif (m1 // 4 + j == m2 // 4):
                    ans_add_mod = (calc_moves(c[0], 'a') ** m1) * (base[0] ** m2) % 1000000007
                else:
                    ans_add_mod = (base[0] ** (m2 - m1)) * (calc_moves(c[0], 'a') ** (m2 - m1)) % 1000000007
                if m1 // 4 + j + min(m1 % 4, m2 % 4) < m2 // 4:
                    ans_add_mod = ans_add_mod + (1000000007 - ans_add) // 2
                ans_add_mod += (1000000007 - ans_add) % 2 * ans_add
                ans_add_mod = (ans_add_mod % 1000000007) % 1000000007
                ans += (ans_add_mod - ans_add) // 2
            ans %= 1000000007
        else:
