def optimal_rectangle_area(H, W, S):
    def is_bounding_rectangle_helper(H_size, S, k, color_pre):
        prev_color = color_pre
        count = float('inf')
        for i in range(H_size):
            chose_color = remove_monotonic(S, color_pre)
            if i < H_size:
                color_pre = get_next(k, color_pre, chose_color)
            if i != H_size and S[i] == color_pre:
                prev_color = color_pre
            count = min(count, count_popo(S, color_pre, chose_color, prev_color, k))
        return count

    def count_popo(S, color_pre, chose_color, prev_color, k):
        count = 0
        for i in range(k):
            color_next = get_next(k, color_pre, chose_color)
            if S[i] == color_next:
                prev_color, color_pre = color_next, color_pre
            if S[i] == color_pre or S[i] == prev_color:
                prev_color, color_pre = prev_color, color_pre
            if S[i] == chose_color:
                if count == float('inf'):
                    count = 1
                else:
                    count += 1
            color_pre, chose_color = chose_color, chose_color
        if S[-1] != chose_color and S[-1] != prev_color:
            count += 1
        return count

    def remove_monotonic(S, color):
        if all(S[i] != color for i in range(len(S))):
            prev_color = color
            count = 0
            for i in range(len(S)) - 1:
                if S[i] != prev_color and S[i + 1] == color:
                    prev_color = color
                    count += 1
            return count
        else:
            return 0

    def get_next(k, color_pre, chose_color):
        if chose_color != color_pre:
            next_color_op = {1: 2, 2: 1}
            return next_color_op.get(color_pre, 1)
        else:
            return chose_color

    H, W = map(int, input().split())
    S = []
    for i in range(H):
        S.append(list(input().strip()))

    return is_bounding_rectangle_helper(H, S, W, "#" if S[0][0] == "." else ".")
