import sys

def max_rectangle_area(H, W, S):
    """
    Finds the maximum possible area of a rectangle Snuke can draw on the board,
    after performing any number of optimal row and column inversions.
    """
    h_drawn = [[0]*W]*H + [[0]*W]*(W-1) + [0]*(W-1)
    w_drawn = [[0]*W]*H + [[0]*W]*(H-1) + [0]*(H-1)

    for i in range(H):
        for j in range(W):
            while h_drawn[i][j] < W and S[i][h_drawn[i][j]] == '.':
                h_drawn[i][h_drawn[i][j]] += 1
            while w_drawn[j][i] < H and S[w_drawn[j][i]][i] == '.':
                w_drawn[w_drawn[j][i]][i] += 1
    max_area = 0
    for i in range(H):
        for j in range(W):
            h = w = 0
            for h_r in range(H):
                while h_r <= i and S[h_r][j] == '#':
                    h_r += 1
                for w_r in range(W):
                    while w_r <= j and S[i][w_r] == '#':
                        w_r += 1
                s = 1
                while h_r < H and h_r - h <= h_drawn[h_r][j]:
                    s += 1
                    h_r += 1
                while w_r < W and w_r - w <= w_drawn[j][w_r]:
                    s += 1
                    w_r += 1
                max_area = max(max_area, s)
    return max_area

